def placeholders(text):
    return sorted(re.findall(r"\{([A-Za-z_][A-Za-z0-9_]*)\}", text or ""))

def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def save_json(path, data):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")

def update_bank(data):
    seen = set()
    for q in data.get("questions", []):
        qid = q.get("question_id")
        if qid not in Q:
            continue
        ml, hi = Q[qid]
        q.setdefault("question_text", {})["ml"] = ml
        q["question_text"]["hi"] = hi
        q.setdefault("translation_status", {})["ml"] = "NEEDS_REVIEW"
        q["translation_status"]["hi"] = "NEEDS_REVIEW"
        seen.add(qid)
        for opt in q.get("options", []):
            oid = opt.get("option_id")
            if oid in OPTION_LABELS:
                oml, ohi = OPTION_LABELS[oid]
                opt["label_translations"] = {"en": opt.get("label", ""), "ml": oml, "hi": ohi}
    missing = set(Q) - seen
    if missing:
        raise ValueError("Question IDs missing from question bank: " + ", ".join(sorted(missing)))
    return len(seen)

def update_templates(data):
    seen = set()
    for t in data.get("templates", []):
        tid = t.get("template_id")
        if tid not in T:
            continue
        ml, hi, ml_name, hi_name, ml_desc, hi_desc = T[tid]
        pattern = t.setdefault("question_pattern", {})
        pattern["ml"] = ml
        pattern["hi"] = hi
        t["template_name_translations"] = {
            "en": t.get("template_name", ""),
            "ml": ml_name,
            "hi": hi_name,
        }
        t["description_translations"] = {
            "en": t.get("description", ""),
            "ml": ml_desc,
            "hi": hi_desc,
        }
        seen.add(tid)
        expected = sorted(t.get("placeholders", []))
        for lang in ("en", "ml", "hi"):
            actual = placeholders(pattern.get(lang, ""))
            if actual != expected:
                raise ValueError(
                    f"Placeholder mismatch for {tid}/{lang}: expected {expected}, found {actual}"
                )
    missing = set(T) - seen
    if missing:
        raise ValueError("Template IDs missing from template file: " + ", ".join(sorted(missing)))
    return len(seen)

def main():
    bank_path = Path(sys.argv[1] if len(sys.argv) > 1 else "question_bank.json")
    template_path = Path(sys.argv[2] if len(sys.argv) > 2 else "question_templates.json")
    if not bank_path.exists() or not template_path.exists():
        raise SystemExit(
            "Could not find both input files. Run from the folder containing them, or pass both paths."
        )
    bank = load_json(bank_path)
    templates = load_json(template_path)
    q_count = update_bank(bank)
    t_count = update_templates(templates)
    bank_out = bank_path.with_name("question_bank_multilingual.json")
    template_out = template_path.with_name("question_templates_multilingual.json")
    save_json(bank_out, bank)
    save_json(template_out, templates)
    # Re-open output to verify valid JSON.
    load_json(bank_out)
    load_json(template_out)
    print(f"Updated {q_count} questions -> {bank_out}")
    print(f"Updated {t_count} templates -> {template_out}")
    print("JSON syntax and template placeholders validated.")
    print("Note: translations are marked NEEDS_REVIEW for native-speaker review.")

if __name__ == "__main__":
    main()
